{
          pages:[
              "[
                \"\",
                {\"text\":\"§lOres: The All Inclusive Guide
\"},
                {\"text\":\"§lBy \"},
                {\"text\":\"§kREDACTED

\"},
                {\"text\":\"Ores come in two main varieties, stone and deepslate. \"},
                {\"text\":\"Stone ores are found higher up underground while deepslate ores are found deep underground. \"}
              ]",
              "[
                {\"text\":\"Each of these ores come in many varieties, including coal, iron, copper, emerald, redstone, gold, diamond, and zinc. \"},
                {\"text\":\"In this guide, we will examine each type of ore and where you can find them.\"}
              ]",
              "[
                {\"text\":\"Coal is found in large clumps in higher elevations, particularly on surfaces of mountaintops.\"}
              ]",
              "[
                {\"text\":\"Iron, zinc and copper are found in most elevations with the best rates at medium heights\"},
                {\"text\":\"Iron can also be found in very large veins with tuff, and copper with granite.\"}
              ]",
              "[
                {\"text\":\"Emerald is found almost exclusively in mountainous areas in mid range elevations. \"},
                {\"text\":\"Deepslate emerald ore is one of the rarest things you can obtain.

\"},
                {\"text\":\"Redstone ore glows when touched, and is found deep underground.\"}
              ]",
              "[
                {\"text\":\"Gold ore is found deep underground in most biomes, \"},
                {\"text\":\"but in the Mesa biome it can be found in large quantities near the surface.

\"},
                {\"text\":\"Diamonds are the most valuable ore and found in small quantities deep underground.\"}
              ]"
            ],
            title:Ores,
            author:Unknown,
            display:{Lore:["Found in the ancient Stronghold"]}
            }

