{
          pages:[
              "[
                \"\",
                {\"text\":\"§kREDACTED\"},
                {\"text\":\"§l’s Journal
Day 85

\"},
                {\"text\":\"§kREDACTED\"},
                {\"text\":\" testified to the council that I was the one who pushed \"},
                {\"text\":\"§kREDACTED\"},
                {\"text\":\" into the lava during our adventure through the Nether. This is a flat out lie, it was \"},
                {\"text\":\"§kREDACTED\"},
                {\"text\":\" that did it!\"}
              ]",
              "[
                {\"text\":\"I can’t believe the council thought I would’ve pushed my best friend into lava. \"},
                {\"text\":\"They will pay for this!\"}
              ]"
            ],
            title:Journal,
            author:Unknown,
            display:{Lore:["Found in the ancient Stronghold"]}
            }

{
          pages:[
              "[
                \"\",
                {\"text\":\"§kREDACTED\"},
                {\"text\":\"§l’s Journal
Day 120

\"},
                {\"text\":\"Today I was sent to prison by the council for stealing cake from the kitchen. \"},
                {\"text\":\"I’m not denying that I did it, but prison!? For stealing a cake!?!? \"}
              ]",
              "[
                {\"text\":\"The council goes too far sometimes. \"},
                {\"text\":\"I hope they vote to release me sooner than the one week sentence I got.\"}
              ]"
            ],
            title:Journal,
            author:Unknown,
            display:{Lore:["Found in the ancient Stronghold"]}
            }

{
          pages:[
              "[
                \"\",
                {\"text\":\"§kREDACTED\"},
                {\"text\":\"§l’s Journal
Day 203

\"},
                {\"text\":\"I attempted to break into the research lab to destroy research on The Asteroid. \"},
                {\"text\":\"The researchers must be stopped… they are tampering with the dark powers they know nothing about. \"},
                {\"text\":\"They will kill us all…\"}
              ]"
            ],
            title:Journal,
            author:Unknown,
            display:{Lore:["Found in the ancient Stronghold"]}
            }

{
          pages:[
              "[
                \"\",
                {\"text\":\"§kREDACTED\"},
                {\"text\":\"§l’s Journal
Day 280

\"},
                {\"text\":\"I was sent here for refusing to believe in their flying mystical hunk of junk, The One Above All. \"},
                {\"text\":\"I don’t believe they really saw her in visions. \"}
              ]",
              "[
                {\"text\":\"I don’t think she even really exists! \"},
                {\"text\":\"I think the researchers are using it to justify their dangerous experiments. \"}
              ]"
            ],
            title:Journal,
            author:Unknown,
            display:{Lore:["Found in the ancient Stronghold"]}
            }

{
          pages:[
              "[
                \"\",
                {\"text\":\"Day Tallies

\"},
                {\"text\":\"IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII \"},
                {\"text\":\"IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII \"}
              ]",
              "[
                {\"text\":\"IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII \"},
                {\"text\":\"IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII \"},
                {\"text\":\"IIIII IIIII IIIII IIIII IIIII IIIII IIIII IIIII II\"}
              ]"
            ],
            title:Journal,
            author:Unknown,
